public class Constants {
    public static int minusOne() {
        return -1;
    }

    public static int zero() {
        return 0;
    }

    public static int one() {
        return 1;
    }

    public static int two() {
        return 2;
    }

    public static int three() {
        return 3;
    }

    public static int four() {
        return 4;
    }

    public static int five() {
        return 5;
    }

    public static int addByte(int value) {
        return value + 100;
    }

    public static int addNegativeByte(int value) {
        return value + -100;
    }

    public static int addShort(int value) {
        return value + 30000;
    }

    public static int subtractShort(int value) {
        return value - 30000;
    }

    public static int negativeShort() {
        return -20000;
    }
}
